package UAV_FlightControl
public

  data AttitudeData
  end AttitudeData;

  data CommandData
  end CommandData;

  system FlightControlSystem
  end FlightControlSystem;

  system implementation FlightControlSystem.Impl
    subcomponents
      ControlUnit: process ControlProcess.Impl;
      IMU: device IMU_Sensor;
      Servo: device ServoActuator;
    connections
      C1: port IMU.SensorData -> ControlUnit.SensorIn;
      C2: port ControlUnit.ControlOut -> Servo.Command;
  end FlightControlSystem.Impl;

  process ControlProcess
  end ControlProcess;

  process implementation ControlProcess.Impl
    subcomponents
      SensorAcq: thread SensorAcqThread;
      ControlLaw: thread ControlLawThread;
    connections
      L1: port SensorAcq.Attitude -> ControlLaw.AttitudeIn;
  end ControlProcess.Impl;

  thread SensorAcqThread
    properties
      Dispatch_Protocol => Periodic;
      Period => 10 ms;
      Priority => 10;
  end SensorAcqThread;

  thread ControlLawThread
    properties
      Dispatch_Protocol => Periodic;
      Period => 20 ms;
      Priority => 20;
  end ControlLawThread;

  processor FlightController
  end FlightController;

  device IMU_Sensor
    features
      SensorData: out data port AttitudeData;
  end IMU_Sensor;

  device ServoActuator
    features
      Command: in data port CommandData;
  end ServoActuator;

end UAV_FlightControl;

package Automotive_ESC
public

  data WheelSpeedData
  end WheelSpeedData;

  data YawMomentCommand
  end YawMomentCommand;

  system ESCSystem
  end ESCSystem;

  system implementation ESCSystem.Impl
    subcomponents
      ESC_ECU: process ESCControlProcess.Impl;
      WheelSensor: device WheelSpeedSensor;
      BrakeActuator: device BrakeActuator;
    connections
      C1: port WheelSensor.WheelSpeed -> ESC_ECU.WheelSpeedIn;
      C2: port ESC_ECU.BrakeCommand -> BrakeActuator.BrakeCmd;
  end ESCSystem.Impl;

  process ESCControlProcess
  end ESCControlProcess;

  process implementation ESCControlProcess.Impl
    subcomponents
      WheelAcq: thread WheelSpeedAcqThread;
      StateEst: thread VehicleStateEstThread;
      YawCtrl: thread YawControlThread;
    connections
      L1: port WheelAcq.WheelSpeed -> StateEst.WheelSpeedIn;
      L2: port StateEst.VehicleState -> YawCtrl.StateIn;
  end ESCControlProcess.Impl;

  thread WheelSpeedAcqThread
    properties
      Dispatch_Protocol => Periodic;
      Period => 5 ms;
      Priority => 10;
  end WheelSpeedAcqThread;

  thread VehicleStateEstThread
    properties
      Dispatch_Protocol => Periodic;
      Period => 10 ms;
      Priority => 20;
  end VehicleStateEstThread;

  thread YawControlThread
    properties
      Dispatch_Protocol => Periodic;
      Period => 10 ms;
      Priority => 30;
  end YawControlThread;

  processor ESC_Processor
  end ESC_Processor;

  device WheelSpeedSensor
    features
      WheelSpeed: out data port WheelSpeedData;
  end WheelSpeedSensor;

  device BrakeActuator
    features
      BrakeCmd: in data port YawMomentCommand;
  end BrakeActuator;

end Automotive_ESC;

package Industrial_RobotJoint
public

  data JointAngleData
  end JointAngleData;

  data TorqueCommand
  end TorqueCommand;

  system RobotJointController
  end RobotJointController;

  system implementation RobotJointController.Impl
    subcomponents
      JointCtrl: process JointControlProcess.Impl;
      Encoder: device JointEncoder;
      ServoDrive: device ServoDriver;
    connections
      C1: port Encoder.Angle -> JointCtrl.AngleIn;
      C2: port JointCtrl.TorqueCmd -> ServoDrive.TorqueIn;
  end RobotJointController.Impl;

  process JointControlProcess
  end JointControlProcess;

  process implementation JointControlProcess.Impl
    subcomponents
      AngleAcq: thread JointAngleAcqThread;
      Interp: thread TrajectoryInterpThread;
      ServoCtrl: thread ServoControlThread;
      SafetyMon: thread SafetyMonitorThread;
    connections
      L1: port AngleAcq.Angle -> Interp.AngleIn;
      L2: port Interp.Setpoint -> ServoCtrl.SetpointIn;
      L3: port ServoCtrl.TorqueCmd -> SafetyMon.TorqueIn;
  end JointControlProcess.Impl;

  thread JointAngleAcqThread
    properties
      Dispatch_Protocol => Periodic;
      Period => 2 ms;
      Priority => 20;
  end JointAngleAcqThread;

  thread TrajectoryInterpThread
    properties
      Dispatch_Protocol => Periodic;
      Period => 4 ms;
      Priority => 30;
  end TrajectoryInterpThread;

  thread ServoControlThread
    properties
      Dispatch_Protocol => Periodic;
      Period => 1 ms;
      Priority => 40;
  end ServoControlThread;

  thread SafetyMonitorThread
    properties
      Dispatch_Protocol => Periodic;
      Period => 10 ms;
      Priority => 10;
  end SafetyMonitorThread;

  processor Industrial_MultiCore
  end Industrial_MultiCore;

  device JointEncoder
    features
      Angle: out data port JointAngleData;
  end JointEncoder;

  device ServoDriver
    features
      TorqueIn: in data port TorqueCommand;
  end ServoDriver;

end Industrial_RobotJoint;
